//@ProcessingGroup("collateral")
@Component("collateral-projector")
public class CollateralProjector extends CollateralEntityProjector {
		
	// core constructor
	public CollateralProjector(ProjectorRegistry registry,
									CollateralRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateCollateralEvent
     */
    @EventHandler( payloadType=CreateCollateralEvent.class )
    public void handle( CreateCollateralEvent event) {
	    LOGGER.info("handling CreateCollateralEvent - " + event );
	    Collateral entity = new Collateral();
            entity.setCollateralId( event.getCollateralId() );
            entity.setAppraisedValue( event.getAppraisedValue() );
            entity.setDescription( event.getDescription() );
            entity.setLocation( event.getLocation() );
            entity.setCollateralType( event.getCollateralType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCollateral( entity );
    }

    /*
     * @param	event UpdateCollateralEvent
     */
    @EventHandler( payloadType=UpdateCollateralEvent.class )
    public void handle( UpdateCollateralEvent event) {
    	LOGGER.info("handling UpdateCollateralEvent - " + event );
    	
	    Collateral entity = new Collateral();
            entity.setCollateralId( event.getCollateralId() );
            entity.setAppraisedValue( event.getAppraisedValue() );
            entity.setDescription( event.getDescription() );
            entity.setLocation( event.getLocation() );
            entity.setLoanAccount( event.getLoanAccount() );
            entity.setCollateralType( event.getCollateralType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCollateral( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCollateral( entity );        
    }
    
    /*
     * @param	event DeleteCollateralEvent
     */
    @EventHandler( payloadType=DeleteCollateralEvent.class )
    public void handle( DeleteCollateralEvent event) {
    	LOGGER.info("handling DeleteCollateralEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	Collateral entity = delete( event.getCollateralId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCollateral( entity );

    }    

    /*
     * @param	event AssignLoanAccountToCollateralEvent
     */
    @EventHandler( payloadType=AssignLoanAccountToCollateralEvent.class)
    public void handle( AssignLoanAccountToCollateralEvent event) {
	    LOGGER.info("handling AssignLoanAccountToCollateralEvent - " + event );

	    // ------------------------------------------
	    // delegate to assignTo
	    // ------------------------------------------
	    Collateral entity = assignLoanAccount( event.getCollateralId(), event.getAssignment() );

	    // ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCollateral( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCollateral( entity );
    }
    

	/*
	 * @param	event UnAssignLoanAccountFromCollateralEvent
	 */
	@EventHandler( payloadType=UnAssignLoanAccountFromCollateralEvent.class)
	public void handle( UnAssignLoanAccountFromCollateralEvent event) {
	    LOGGER.info("handling UnAssignLoanAccountFromCollateralEvent - " + event );

	    // ------------------------------------------
	    // delegate to unAssignFrom
	    // ------------------------------------------
	    Collateral entity = unAssignLoanAccount( event.getCollateralId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindCollateral( entity );
	
		// ------------------------------------------
		// emit to subscribers that find all
		// ------------------------------------------    	
	    emitFindAllCollateral( entity );
	}




    /**
     * Method to retrieve the Collateral via an CollateralPrimaryKey.
     * @param 	id Long
     * @return 	Collateral
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Collateral handle( FindCollateralQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getCollateralId() );
    }
    
    /**
     * Method to retrieve a collection of all Collaterals
     *
     * @param	query	FindAllCollateralQuery 
     * @return 	List<Collateral> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Collateral> handle( FindAllCollateralQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCollateral,
 * but only if the id matches
 *
 * @param		entity	Collateral
 */
	protected void emitFindCollateral( Collateral entity ) {
		LOGGER.info("handling emitFindCollateral" );
		
	    queryUpdateEmitter.emit(FindCollateralQuery.class,
	                            query -> query.getFilter().getCollateralId().equals(entity.getCollateralId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCollateral
	 * 
	 * @param		entity	Collateral
	 */
	protected void emitFindAllCollateral( Collateral entity ) {
		LOGGER.info("handling emitFindAllCollateral" );
		
	    queryUpdateEmitter.emit(FindAllCollateralQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(CollateralProjector.class.getName());

}
